pub const CHATGPT_BASE: &str = "https://chatgpt.com/";
pub const CHATGPT_GG_BASE: &str = "https://chatgpt.com/gg/";
pub const CHATGPT_LEGACY_BASE: &str = "https://chat.openai.com/";
pub const GEMINI_BASE: &str = "https://gemini.google.com/";

pub fn is_chatgpt_gg_url(url: &str) -> bool {
    url.starts_with(CHATGPT_GG_BASE)
}

pub fn is_chatgpt_url(url: &str) -> bool {
    url.starts_with(CHATGPT_BASE) || url.starts_with(CHATGPT_LEGACY_BASE)
}

pub fn is_gemini_url(url: &str) -> bool {
    url.starts_with(GEMINI_BASE)
}

//! LLM Provider Adapter
//!
//! Responsibility:
//!   Transform AgentCallInput → LLM turn → structured AgentCallOutput.
//!
//! Contract:
//!   - Stateless
//!   - No disk I/O
//!   - No polling
//!   - JSON-only response contract
//!   - WebSocket transport abstracted via WsBridge
//!
//! Pipeline:
//!   Input → PromptBuilder → WsBridge → JsonExtractor → OutputAssembler

use serde_json::Value;

use super::call::{AgentCallInput, AgentCallOutput};
use super::ws_server::{WsBridge, WsBridgeError};

/// ------------------------------------------------------------------------
/// Error Domain
/// ------------------------------------------------------------------------

#[derive(Debug)]
pub enum LlmProviderError {
    Transport(WsBridgeError),
    MissingJsonFence,
    JsonDecodeFailure(String),
}

impl std::fmt::Display for LlmProviderError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Transport(e) => write!(f, "transport error: {e}"),
            Self::MissingJsonFence => write!(f, "no fenced json block found"),
            Self::JsonDecodeFailure(e) => write!(f, "invalid json payload: {e}"),
        }
    }
}

impl std::error::Error for LlmProviderError {}

impl From<WsBridgeError> for LlmProviderError {
    fn from(e: WsBridgeError) -> Self {
        Self::Transport(e)
    }
}

/// Send a fully-formed prompt string to the LLM and return the extracted
/// JSON payload. Bypasses PromptBuilder — caller owns the full prompt.
pub async fn call_llm_raw(bridge: &WsBridge, prompt: String, url: &str) -> Result<Value, LlmProviderError> {
    bridge.wait_for_connection().await;
    let tab_id = bridge.open_fresh_tab_with_url(url.to_string()).await.map_err(LlmProviderError::Transport)?;
    let raw = bridge.send_turn(tab_id, prompt).await.map_err(LlmProviderError::Transport)?;
    JsonExtractor::extract(&raw)
}

/// ------------------------------------------------------------------------
/// Public Entry Point
/// ------------------------------------------------------------------------

pub async fn call_llm(bridge: &WsBridge, input: &AgentCallInput, url: &str) -> Result<AgentCallOutput, LlmProviderError> {
    let prompt = PromptBuilder::new(input).build();

    bridge.wait_for_connection().await;

    // clean mode: suppress call_llm url log
    let tab_id = bridge.open_fresh_tab_with_url(url.to_string()).await.map_err(LlmProviderError::Transport)?;

    // clean mode: suppress TURN routing log

    let raw_response = bridge.send_turn(tab_id, prompt).await.map_err(LlmProviderError::Transport)?;

    let payload = JsonExtractor::extract(&raw_response)?;

    Ok(OutputAssembler::assemble(input, payload))
}

/// ------------------------------------------------------------------------
/// Prompt Builder
/// ------------------------------------------------------------------------

struct PromptBuilder<'a> {
    input: &'a AgentCallInput,
}

impl<'a> PromptBuilder<'a> {
    fn new(input: &'a AgentCallInput) -> Self {
        Self { input }
    }

    fn build(&self) -> String {
        let stage = format!("{:?}", self.input.stage);
        let ir = self.serialize_ir();
        let predecessors = self.serialize_predecessors();
        let required = required_fields_for_stage(&stage);

        format!(
            "Capability Node Execution\n\
             ------------------------\n\
             Stage: {stage}\n\
             Node: {node}\n\
             Call: {call}\n\
             \n\
             IR Slice:\n\
             ```json\n{ir}\n```\n\
             \n\
             Predecessor Outputs:\n\
             {predecessors}\n\
             \n\
             Required Output:\n\
             Respond with ONE fenced ```json block only.\n\
             Must include fields:\n\
             {required}",
            stage = stage,
            node = self.input.node_id,
            call = self.input.call_id,
            ir = ir,
            predecessors = predecessors,
            required = required,
        )
    }

    fn serialize_ir(&self) -> String {
        serde_json::to_string_pretty(&self.input.ir_slice).unwrap_or_else(|_| "{}".into())
    }

    fn serialize_predecessors(&self) -> String {
        if self.input.predecessor_outputs.is_empty() {
            return "none".into();
        }

        self.input
            .predecessor_outputs
            .iter()
            .map(|p| format!("node={} stage={:?} payload={}", p.node_id, p.stage, serde_json::to_string(&p.payload).unwrap_or_default()))
            .collect::<Vec<_>>()
            .join("\n")
    }
}

/// ------------------------------------------------------------------------
/// JSON Extraction
/// ------------------------------------------------------------------------

pub struct JsonExtractor;

impl JsonExtractor {
    pub fn extract(text: &str) -> Result<Value, LlmProviderError> {
        let start = Self::find_open(text)?;
        let content = &text[start..];
        let json_str = Self::slice_json(content)?;
        serde_json::from_str(json_str).map_err(|e| LlmProviderError::JsonDecodeFailure(e.to_string()))
    }

    fn find_open(text: &str) -> Result<usize, LlmProviderError> {
        text.find("```json").or_else(|| text.find("```JSON")).map(|i| i + 7).ok_or(LlmProviderError::MissingJsonFence)
    }

    fn slice_json(text: &str) -> Result<&str, LlmProviderError> {
        let end = text.rfind("```").ok_or(LlmProviderError::MissingJsonFence)?;
        Ok(text[..end].trim())
    }
}

/// ------------------------------------------------------------------------
/// Output Assembly
/// ------------------------------------------------------------------------

struct OutputAssembler;

impl OutputAssembler {
    fn assemble(input: &AgentCallInput, payload: Value) -> AgentCallOutput {
        let proof_id = payload.get("proof_id").and_then(|v| v.as_str()).map(str::to_owned);

        let emitted_delta_ids = payload.get("emitted_delta_ids").and_then(|v| v.as_array()).map(|arr| arr.iter().filter_map(|v| v.as_str().map(str::to_owned)).collect()).unwrap_or_default();

        AgentCallOutput { call_id: input.call_id.clone(), node_id: input.node_id.clone(), payload, proof_id, emitted_delta_ids, stage: input.stage.clone() }
    }
}

/// ------------------------------------------------------------------------
/// Stage Schema
/// ------------------------------------------------------------------------

fn required_fields_for_stage(stage: &str) -> &'static str {
    match stage {
        "Observe" => {
            r#"{
  "observation": "<string>",
  "hottest_modules": ["<module_id>"],
  "issues_found": ["<string>"]
}"#
        }

        "Learn" => {
            r#"{
  "rationale": "<string>",
  "proposed_kind": "<split_module|merge_modules|move_artifact|rename_artifact|add_edge|remove_edge>",
  "target_artifact_id": "<string>",
  "destination_id": "<string|null>",
  "change_payload": {
    "type": "<add_module|add_struct|add_field|add_trait|add_trait_function|add_impl|add_function|add_enum|add_enum_variant|update_struct_visibility|remove_field|rename_artifact|add_module_edge|add_call_edge|record_reward>",
    "...fields per type — examples below...": null,
    "ADD_MODULE":    { "module_id": "<id>", "name": "<name>", "visibility": "<public|private|pub_crate|pub_super>", "description": "<string>" },
    "ADD_STRUCT":    { "module": "<module_id>", "struct_id": "<id>", "name": "<name>" },
    "ADD_FIELD":     { "struct_id": "<id>", "field": { "name": "<name>", "ty": { "name": "<type>", "kind": "scalar", "params": [], "ref_kind": "none" } } },
    "ADD_TRAIT":     { "module": "<module_id>", "trait_id": "<id>", "name": "<name>" },
    "ADD_FUNCTION":  { "function_id": "<id>", "impl_id": "<id>", "signature": { "name": "<name>", "visibility": "public", "is_async": false, "is_unsafe": false, "inputs": [], "outputs": [], "generics": [], "where_clauses": [], "lifetime_params": [], "trait_function": "<trait_fn_id>", "doc": null } },
    "ADD_MODULE_EDGE": { "from": "<module_id>", "to": "<module_id>", "rationale": "<string>" },
    "RENAME_ARTIFACT": { "kind": "<module|struct|function>", "old_id": "<id>", "new_id": "<id>" }
  }
}"#
        }

        "Decide" => {
            r#"{
  "proof_id": "<string>",
  "verification_notes": "<string>"
}"#
        }

        "Plan" => {
            r#"{
  "decision": "<accept|reject>",
  "admission_id": "<string>",
  "rationale": "<string>"
}"#
        }

        _ => {
            r#"{
  "observation": "<string>",
  "rationale": "<string>"
}"#
        }
    }
}

use crate::llm_domains::{is_chatgpt_gg_url, is_chatgpt_url, is_gemini_url};
use serde_json::Value;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SiteType {
    ChatGptPrivate,
    ChatGptGroup,
    Gemini,
    Unknown,
}

impl SiteType {
    pub fn from_url(url: &str) -> Self {
        if is_chatgpt_gg_url(url) {
            return SiteType::ChatGptGroup;
        }
        if is_chatgpt_url(url) {
            return SiteType::ChatGptPrivate;
        }
        if is_gemini_url(url) {
            return SiteType::Gemini;
        }
        SiteType::Unknown
    }
}

/// The result of parsing one inbound frame.
#[derive(Debug)]
pub enum FrameResult {
    Delta(String),
    Snapshot(String),
    Done,
    Ignore,
}

pub fn classify_frame(site: SiteType, raw: &str) -> FrameResult {
    match site {
        SiteType::ChatGptPrivate => classify_chatgpt_private(raw),
        SiteType::ChatGptGroup => classify_chatgpt_group(raw),
        SiteType::Gemini => classify_gemini(raw),
        SiteType::Unknown => FrameResult::Ignore,
    }
}

pub struct FrameAssembler {
    site: SiteType,
    deltas: Vec<String>,
    raw: String,
}

impl FrameAssembler {
    pub fn new(site: SiteType) -> Self {
        Self { site, deltas: Vec::new(), raw: String::new() }
    }

    pub fn set_site(&mut self, site: SiteType) {
        self.site = site;
    }

    pub fn reset(&mut self) {
        self.deltas.clear();
        self.raw.clear();
    }

    pub fn push(&mut self, payload: &str) -> Option<String> {
        match self.site {
            SiteType::Gemini => {
                match classify_frame(self.site, payload) {
                    FrameResult::Snapshot(text) => {
                        // Gemini frames are typically full snapshots; replace instead of append.
                        self.raw.clear();
                        self.raw.push_str(&text);
                        if let Some(fenced) = try_extract_complete_fenced_json(&self.raw) {
                            self.reset();
                            return Some(fenced);
                        }
                        None
                    }
                    FrameResult::Delta(text) => {
                        self.raw.push_str(&text);
                        if let Some(fenced) = try_extract_complete_fenced_json(&self.raw) {
                            self.reset();
                            return Some(fenced);
                        }
                        None
                    }
                    _ => None,
                }
            }
            _ => match classify_frame(self.site, payload) {
                FrameResult::Delta(text) => {
                    self.deltas.push(text);
                    None
                }
                FrameResult::Snapshot(text) => {
                    self.reset();
                    Some(text)
                }
                FrameResult::Done => {
                    let assembled = self.deltas.join("");
                    self.reset();
                    if assembled.is_empty() {
                        None
                    } else {
                        Some(assembled)
                    }
                }
                FrameResult::Ignore => None,
            },
        }
    }
}

fn classify_chatgpt_private(raw: &str) -> FrameResult {
    let data = raw.strip_prefix("data: ").unwrap_or(raw).trim();
    if data.is_empty() {
        return FrameResult::Ignore;
    }
    if data == "[DONE]" {
        return FrameResult::Done;
    }
    let v: Value = match serde_json::from_str(data) {
        Ok(v) => v,
        Err(_) => {
            if let Some(fenced) = extract_fenced_json(data) {
                return FrameResult::Snapshot(fenced);
            }
            return FrameResult::Ignore;
        }
    };

    if let Some(fenced) = find_fenced_json_in_value(&v) {
        return FrameResult::Snapshot(fenced);
    }

    let obj = match v.as_object() {
        Some(o) => o,
        None => return FrameResult::Ignore,
    };
    if obj.get("type").and_then(|t| t.as_str()) == Some("message_stream_complete") {
        return FrameResult::Done;
    }
    if obj.get("type").and_then(|t| t.as_str()) == Some("message") {
        let text = obj.get("content").and_then(|c| c.get("parts")).and_then(|p| p.as_array()).and_then(|a| a.first()).and_then(|v| v.as_str()).unwrap_or("");
        if !text.is_empty() {
            return FrameResult::Snapshot(text.to_string());
        }
    }
    if obj.get("object").and_then(|v| v.as_str()) == Some("chat.completion.chunk") {
        let content = obj.get("choices").and_then(|c| c.as_array()).and_then(|arr| arr.first()).and_then(|c| c.get("delta")).and_then(|d| d.get("content")).and_then(|v| v.as_str());
        return match content {
            Some(s) if !s.is_empty() => FrameResult::Delta(s.to_string()),
            _ => FrameResult::Ignore,
        };
    }
    if let Some(delta) = obj.get("delta").and_then(|d| d.as_str()) {
        if !delta.is_empty() {
            return FrameResult::Delta(delta.to_string());
        }
    }
    if let Some(op) = obj.get("o").and_then(|o| o.as_str()) {
        match op {
            "append" => {
                let p = obj.get("p").and_then(|p| p.as_str()).unwrap_or("");
                if p.contains("parts") {
                    if let Some(s) = obj.get("v").and_then(|v| v.as_str()) {
                        if !s.is_empty() {
                            return FrameResult::Delta(s.to_string());
                        }
                    }
                }
            }
            "patch" => {
                if let Some(arr) = obj.get("v").and_then(|v| v.as_array()) {
                    let mut out = String::new();
                    for item in arr {
                        if item.get("o").and_then(|o| o.as_str()) != Some("append") {
                            continue;
                        }
                        let p = item.get("p").and_then(|p| p.as_str()).unwrap_or("");
                        if p.contains("parts") {
                            if let Some(s) = item.get("v").and_then(|v| v.as_str()) {
                                out.push_str(s);
                            }
                        }
                    }
                    if !out.is_empty() {
                        return FrameResult::Delta(out);
                    }
                }
            }
            _ => {}
        }
    }
    if let Some(text) = obj.get("v").and_then(|v| v.as_str()) {
        if !text.is_empty() {
            return FrameResult::Delta(text.to_string());
        }
    }
    if let Some(arr) = obj.get("v").and_then(|v| v.as_array()) {
        let mut out = String::new();
        for item in arr {
            if item.get("o").and_then(|o| o.as_str()) != Some("append") {
                continue;
            }
            let p = item.get("p").and_then(|p| p.as_str()).unwrap_or("");
            if p.contains("parts") {
                if let Some(s) = item.get("v").and_then(|v| v.as_str()) {
                    out.push_str(s);
                }
            }
        }
        if !out.is_empty() {
            return FrameResult::Delta(out);
        }
    }
    FrameResult::Ignore
}

fn classify_chatgpt_group(raw: &str) -> FrameResult {
    let data = raw.strip_prefix("data: ").unwrap_or(raw).trim();
    if data.is_empty() {
        return FrameResult::Ignore;
    }
    let v: Value = match serde_json::from_str(data) {
        Ok(v) => v,
        Err(_) => return FrameResult::Ignore,
    };
    if let Some(arr) = v.as_array() {
        return classify_calpico_array(arr);
    }
    FrameResult::Ignore
}

fn classify_gemini(raw: &str) -> FrameResult {
    let data = raw.strip_prefix("data: ").unwrap_or(raw).trim();
    if data.is_empty() {
        return FrameResult::Ignore;
    }
    let data = strip_leading_length_line(data);
    // Gemini often sends JSON arrays (wrb.fr) with embedded JSON strings.
    if let Ok(v) = serde_json::from_str::<Value>(data) {
        let mut out = String::new();
        collect_gemini_fragments(&v, &mut out, 0);
        if !out.is_empty() {
            if out.contains("```json") {
                return FrameResult::Snapshot(out);
            }
            return FrameResult::Delta(out);
        }
    } else if let Some(fenced) = extract_fenced_json(data) {
        return FrameResult::Snapshot(fenced);
    }
    FrameResult::Ignore
}

fn strip_leading_length_line(input: &str) -> &str {
    let mut chars = input.chars();
    let mut idx = 0usize;
    let mut saw_digit = false;
    while let Some(c) = chars.next() {
        if c.is_ascii_digit() {
            saw_digit = true;
            idx += c.len_utf8();
            continue;
        }
        if (c == '\n' || c == '\r') && saw_digit {
            let rest = input[idx..].trim_start_matches(['\r', '\n']);
            return rest;
        }
        break;
    }
    input
}

fn collect_gemini_fragments(v: &Value, out: &mut String, depth: usize) {
    // Gemini's wrb.fr payloads are deeply nested; keep this high enough to reach text nodes.
    if depth > 12 {
        return;
    }
    match v {
        Value::String(s) => {
            if s.starts_with('{') || s.starts_with('[') {
                if let Ok(inner) = serde_json::from_str::<Value>(s) {
                    collect_gemini_fragments(&inner, out, depth + 1);
                    return;
                }
            }
            if s.contains("```json") {
                out.push_str(s);
            }
        }
        Value::Array(arr) => {
            for item in arr {
                collect_gemini_fragments(item, out, depth + 1);
            }
        }
        Value::Object(map) => {
            for val in map.values() {
                collect_gemini_fragments(val, out, depth + 1);
            }
        }
        _ => {}
    }
}

fn classify_calpico_array(arr: &[Value]) -> FrameResult {
    for envelope in arr {
        if envelope.get("type").and_then(|t| t.as_str()) != Some("message") {
            continue;
        }
        let payload = match envelope.get("payload") {
            Some(p) => p,
            None => continue,
        };
        if payload.get("type").and_then(|t| t.as_str()) != Some("calpico-message-add") {
            continue;
        }
        let msg = match payload.get("payload").and_then(|p| p.get("message")) {
            Some(m) => m,
            None => continue,
        };
        if msg.get("role").and_then(|r| r.as_str()) != Some("assistant") {
            continue;
        }
        let raw_messages = match msg.get("raw_messages").and_then(|v| v.as_array()) {
            Some(a) => a,
            None => continue,
        };
        for raw_msg in raw_messages {
            let author_role = raw_msg.get("author").and_then(|a| a.get("role")).and_then(|r| r.as_str()).unwrap_or("");
            if author_role != "assistant" {
                continue;
            }
            let channel = raw_msg.get("channel").and_then(|c| c.as_str()).unwrap_or("");
            if channel != "final" {
                continue;
            }
            let text = raw_msg.get("content").and_then(|c| c.get("parts")).and_then(|p| p.as_array()).and_then(|a| a.first()).and_then(|v| v.as_str()).unwrap_or("");
            if !text.is_empty() {
                return FrameResult::Snapshot(text.to_string());
            }
        }
    }
    FrameResult::Ignore
}

fn find_fenced_json_in_value(v: &Value) -> Option<String> {
    match v {
        Value::String(s) => extract_fenced_json(s),
        Value::Array(arr) => arr.iter().find_map(find_fenced_json_in_value),
        Value::Object(map) => map.values().find_map(find_fenced_json_in_value),
        _ => None,
    }
}

fn extract_fenced_json(text: &str) -> Option<String> {
    let start = text.find("```json")?;
    let rest = &text[start..];
    let end = rest.rfind("```")?;
    if end <= 6 {
        return None;
    }
    Some(rest[..end + 3].to_string())
}

pub fn try_extract_complete_fenced_json(raw: &str) -> Option<String> {
    let start = raw.find("```json")?;
    let after_fence = &raw[start + 7..];
    // Find the closing ``` — must be after at least one character of content.
    let end = after_fence.rfind("```")?;
    if end == 0 {
        return None;
    }
    let inner = after_fence[..end].trim();
    // Validate as-is — do NOT re-escape; the string is already decoded by serde.
    if serde_json::from_str::<serde_json::Value>(inner).is_ok() {
        return Some(format!("```json\n{}\n```", inner));
    }
    None
}

