pub fn apply_read_only(deltas: &[Delta], roots: &[PathBuf], max_output_lines: usize) -> (String, Vec<DeltaOutcome>, Option<String>) {
    let mut output = String::new();
    let mut results = Vec::new();
    let mut error: Option<String> = None;
    let mut repairs = Vec::new();

    for delta in deltas {
        let delta = repair_delta_path(delta, roots, &mut repairs);
        match executor_dispatch::execute_read_only(&delta, roots, max_output_lines) {
            Ok((msg, out)) => {
                results.push(DeltaOutcome { delta: delta.clone(), status: "ok".into(), message: msg });
                output.push_str(out.trim_end_matches('\n'));
                output.push('\n');
            }
            Err(e) => {
                let msg = format!("ERROR: {e}");
                results.push(DeltaOutcome { delta: delta.clone(), status: "error".into(), message: msg.clone() });
                output.push_str(&msg);
                output.push('\n');
                let _ = error.get_or_insert(msg);
            }
        }
    }
    if !repairs.is_empty() {
        output.push_str("[delta_repair]\n");
        for r in repairs {
            output.push_str(&format!("{} => {} ({})\n", delta_label(&r.original), delta_label(&r.repaired), r.reason));
        }
    }

    (output, results, error)
}

pub fn summarize_deltas(deltas: &[Delta]) -> Vec<serde_json::Value> {
    deltas
        .iter()
        .map(|d| match d {
            Delta::ReadFile { path } => serde_json::json!({"type":"read_file","path":path}),
            Delta::ListDir { path } => serde_json::json!({"type":"list_dir","path":path}),
            Delta::ReadCommand { command, args } => serde_json::json!({"type":"read_command","command":command,"args":args}),
            Delta::WriteFile { path, .. } => serde_json::json!({"type":"write_file","path":path}),
            Delta::ReplaceText { path, .. } => serde_json::json!({"type":"replace_text","path":path}),
            Delta::DeleteFile { path } => serde_json::json!({"type":"delete_file","path":path}),
        })
        .collect()
}

pub fn apply_mutations(deltas: &[Delta], roots: &[PathBuf], allowed_write_roots: &[PathBuf], max_output_lines: usize) -> (String, Vec<DeltaOutcome>, Option<String>) {
    let mut output = String::new();
    let mut results = Vec::new();
    let mut error: Option<String> = None;
    let mut repairs = Vec::new();

    for delta in deltas {
        let delta = repair_delta_path(delta, roots, &mut repairs);
        match executor_dispatch::execute_mutation(&delta, roots, allowed_write_roots, max_output_lines) {
            Ok(msg) => {
                results.push(DeltaOutcome { delta: delta.clone(), status: "ok".into(), message: msg.clone() });
                output.push_str(&msg);
                output.push('\n');
            }
            Err(e) => {
                let msg = format!("ERROR: {e}");
                results.push(DeltaOutcome { delta: delta.clone(), status: "error".into(), message: msg.clone() });
                output.push_str(&msg);
                output.push('\n');
                let _ = error.get_or_insert(msg);
            }
        }
    }
    if !repairs.is_empty() {
        output.push_str("[delta_repair]\n");
        for r in repairs {
            output.push_str(&format!("{} => {} ({})\n", delta_label(&r.original), delta_label(&r.repaired), r.reason));
        }
    }

    (output, results, error)
}

fn repair_delta_path(delta: &Delta, roots: &[PathBuf], repairs: &mut Vec<DeltaRepairLog>) -> Delta {
    let root = roots.get(0).cloned().unwrap_or_else(|| PathBuf::from("/"));
    match delta {
        Delta::ReadFile { path } | Delta::ListDir { path } => {
            let p = Path::new(path);
            if p.is_absolute() && !p.exists() {
                let repaired = match delta {
                    Delta::ReadFile { .. } => Delta::ReadFile { path: root.display().to_string() },
                    Delta::ListDir { .. } => Delta::ListDir { path: root.display().to_string() },
                    _ => delta.clone(),
                };
                repairs.push(DeltaRepairLog { original: delta.clone(), repaired: repaired.clone(), reason: "path does not exist; redirected to workspace root".to_string() });
                return repaired;
            }
            delta.clone()
        }
        _ => delta.clone(),
    }
}

fn delta_label(delta: &Delta) -> String {
    match delta {
        Delta::ReadFile { path } => format!("read_file {}", path),
        Delta::ListDir { path } => format!("list_dir {}", path),
        Delta::ReadCommand { command, args } => format!("read_command {} {}", command, args.join(" ")),
        Delta::WriteFile { path, .. } => format!("write_file {}", path),
        Delta::ReplaceText { path, .. } => format!("replace_text {}", path),
        Delta::DeleteFile { path } => format!("delete_file {}", path),
    }
}

pub(crate) fn resolve_path(path: &str, roots: &[PathBuf], allow_nonexistent: bool) -> Result<PathBuf, String> {
    let p = Path::new(path);
    if has_parent_dir_component(&[path.to_string()]) {
        return Err(format!("path contains '..': {}", path));
    }

    let resolved = anchor(p, &roots[0]);

    if !is_within_roots(&resolved, roots) {
        return Err(format!("path escapes allowed roots: {}", resolved.display()));
    }

    if !allow_nonexistent && !resolved.exists() {
        return Err(format!("path does not exist: {}", resolved.display()));
    }

    Ok(resolved)
}

fn anchor(p: &Path, root: &Path) -> PathBuf {
    if p.is_absolute() {
        p.to_path_buf()
    } else {
        root.join(p)
    }
}

pub(crate) fn is_within_roots(path: &Path, roots: &[PathBuf]) -> bool {
    roots.iter().any(|root| path.starts_with(root))
}

pub(crate) fn has_parent_dir_component(args: &[String]) -> bool {
    args.iter().any(|a| a.split('/').any(|c| c == ".."))
}

pub(crate) fn truncate_lines(text: &str, max_lines: usize) -> String {
    let mut iter = text.lines();
    let kept: Vec<&str> = iter.by_ref().take(max_lines).collect();
    let remaining = iter.count();
    let mut out = kept.join("\n");
    if remaining > 0 {
        out.push_str(&format!("\n... [{} lines truncated] ...", remaining));
    }
    out
}

use std::collections::HashMap;
use std::path::Path;

use serde::{Deserialize, Serialize};

use super::capability::Capability;
use super::dag::TaskNode;

const COST_PATH: &str = "/workspace/ai_sandbox/canon/agent_logs/capability_costs.json";

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct CapabilityCost {
    pub latency_avg: f64,
    pub failure_rate: f64,
    pub samples: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct CapabilityCostTable {
    pub costs: HashMap<Capability, CapabilityCost>,
}

impl CapabilityCostTable {
    pub fn load() -> Self {
        std::fs::read_to_string(COST_PATH).ok().and_then(|s| serde_json::from_str::<CapabilityCostTable>(&s).ok()).unwrap_or_default()
    }

    pub fn save(&self) {
        if let Ok(pretty) = serde_json::to_string_pretty(self) {
            let _ = std::fs::create_dir_all(Path::new(COST_PATH).parent().unwrap_or(Path::new(".")));
            let _ = std::fs::write(COST_PATH, pretty);
        }
    }

    pub fn update(&mut self, cap: Capability, latency_ms: f64, success: bool, decay: f64) {
        let decay = decay.clamp(0.0, 1.0);
        let entry = self.costs.entry(cap).or_default();
        let failure = if success { 0.0 } else { 1.0 };
        if entry.samples == 0 {
            entry.latency_avg = latency_ms;
            entry.failure_rate = failure;
        } else {
            entry.latency_avg = (1.0 - decay) * entry.latency_avg + decay * latency_ms;
            entry.failure_rate = (1.0 - decay) * entry.failure_rate + decay * failure;
        }
        entry.samples = entry.samples.saturating_add(1);
    }

    pub fn node_cost(&self, caps: &[Capability], latency_weight: f64, failure_weight: f64) -> f64 {
        caps.iter().map(|c| self.costs.get(c)).flatten().map(|c| latency_weight * c.latency_avg + failure_weight * c.failure_rate).sum()
    }

    pub fn avg_latency(&self) -> f64 {
        let mut total = 0.0;
        let mut count = 0u64;
        for c in self.costs.values() {
            if c.samples > 0 {
                total += c.latency_avg;
                count += 1;
            }
        }
        if count == 0 {
            0.0
        } else {
            total / count as f64
        }
    }

    pub fn avg_failure(&self) -> f64 {
        let mut total = 0.0;
        let mut count = 0u64;
        for c in self.costs.values() {
            if c.samples > 0 {
                total += c.failure_rate;
                count += 1;
            }
        }
        if count == 0 {
            0.0
        } else {
            total / count as f64
        }
    }

    pub fn summary(&self, max_entries: usize, latency_weight: f64, failure_weight: f64) -> String {
        let mut entries: Vec<(Capability, f64, f64, f64)> = self
            .costs
            .iter()
            .map(|(cap, cost)| {
                let score = latency_weight * cost.latency_avg + failure_weight * cost.failure_rate;
                (*cap, cost.latency_avg, cost.failure_rate, score)
            })
            .collect();
        entries.sort_by(|a, b| b.3.partial_cmp(&a.3).unwrap_or(std::cmp::Ordering::Equal));
        entries.truncate(max_entries);
        let mut lines = Vec::new();
        for (cap, lat, fail, score) in entries {
            lines.push(format!("{:?}: latency_ms={:.1} fail_rate={:.2} cost={:.2}", cap, lat, fail, score));
        }
        lines.join("\n")
    }
}

pub fn apply_node_cost_update(table: &mut CapabilityCostTable, node: &TaskNode, latency_ms: f64, success: bool, decay: f64, latency_weight: f64, failure_weight: f64) -> f64 {
    for cap in &node.required_capabilities {
        table.update(*cap, latency_ms, success, decay);
    }
    table.node_cost(&node.required_capabilities, latency_weight, failure_weight)
}

