const CAPABILITY_POLICY_TOML: &str = "/workspace/ai_sandbox/canon/canon-agent-prompts/capability_policy.toml";

#[derive(Debug, Deserialize)]
struct RawPolicy {
    #[serde(default)]
    pub write_allowed_roots: Vec<String>,
    #[serde(default)]
    pub require_final_render: bool,
}

#[derive(Debug, Clone)]
pub struct CapabilityPolicy {
    pub write_allowed_roots: Vec<PathBuf>,
    pub require_final_render: bool,
    pub max_node_retries: u32,
}
impl Default for CapabilityPolicy {
    fn default() -> Self {
        Self { write_allowed_roots: Vec::new(), require_final_render: false, max_node_retries: default_max_node_retries() }
    }
}

impl CapabilityPolicy {
    pub fn load(workspace_root: &Path) -> Result<Self> {
        let raw_toml = std::fs::read_to_string(CAPABILITY_POLICY_TOML).with_context(|| format!("cannot read {}", CAPABILITY_POLICY_TOML))?;
        let raw: RawPolicy = toml::from_str(&raw_toml).context("cannot parse capability_policy.toml")?;
        let roots = raw
            .write_allowed_roots
            .into_iter()
            .map(|p| {
                let path = Path::new(&p);
                if path.is_absolute() {
                    path.to_path_buf()
                } else {
                    workspace_root.join(path)
                }
            })
            .collect::<Vec<_>>();
        Ok(Self { write_allowed_roots: roots, require_final_render: raw.require_final_render, max_node_retries: default_max_node_retries() })
        // max_node_retries is patched in by mod.rs after loading CapabilityConfig
    }
}

use super::capability::CapabilityClass;

const RESET: &str = "\x1b[0m";
const GRAY: &str = "\x1b[90m";
const GREEN: &str = "\x1b[32m";
const YELLOW: &str = "\x1b[33m";
const RED: &str = "\x1b[31m";
const BLUE: &str = "\x1b[34m";
const MAGENTA: &str = "\x1b[35m";
const CYAN: &str = "\x1b[36m";

pub fn tag(label: &str, color: &str) -> String {
    format!("{}[{}]{}", color, label, RESET)
}

pub fn info(label: &str, msg: &str) -> String {
    format!("{} {}", tag(label, BLUE), msg)
}

pub fn warn(label: &str, msg: &str) -> String {
    format!("{} {}", tag(label, YELLOW), msg)
}

pub fn err(label: &str, msg: &str) -> String {
    format!("{} {}", tag(label, RED), msg)
}

pub fn phase(label: &str, msg: &str) -> String {
    format!("{} {}", tag(label, MAGENTA), msg)
}

pub fn llm(msg: &str) -> String {
    format!("{} {}", tag("llm", CYAN), msg)
}

pub fn mode_label(class: CapabilityClass) -> (&'static str, &'static str) {
    match class {
        CapabilityClass::Observe => ("Observe", GREEN),
        CapabilityClass::Verify => ("Verify", YELLOW),
        CapabilityClass::Mutate => ("Mutate", RED),
    }
}

pub fn mode_tag(class: CapabilityClass) -> String {
    let (label, color) = mode_label(class);
    tag(label, color)
}

pub fn dim(msg: &str) -> String {
    format!("{}{}{}", GRAY, msg, RESET)
}

pub fn truncate(s: &str, max: usize) -> String {
    if s.len() <= max {
        return s.to_string();
    }
    let mut out = s.chars().take(max).collect::<String>();
    out.push_str("…");
    out
}

