static WORKERS: Lazy<Mutex<HashMap<String, mpsc::Sender<LlmRequest>>>> = Lazy::new(|| Mutex::new(HashMap::new()));
static NEXT_REQ_ID: AtomicU64 = AtomicU64::new(1);

